if(flt_dh_signed GT 180, calc(flt_dh_signed, flt_dh_signed - 360));
if(flt_dh_signed LT -180, calc(flt_dh_signed, flt_dh_signed + 360));

calc(flt_dh, flt_dh_signed);
if(flt_dh LT 0, calc(flt_dh, 0 - flt_dh));
calc(flt_dv, flt_v - view.vlookat);
if(flt_dv LT 0, calc(flt_dv, 0 - flt_dv));
calc(flt_df, flt_fov - view.fov);
if(flt_df LT 0, calc(flt_df, 0 - flt_df));
calc(flt_dist, flt_dh + flt_dv * 0.6 + flt_df * 0.25);

set(flt_time_min, 1.4);
set(flt_time_max, 5.0);
set(flt_time_per_deg, 0.032);
calc(flt_t, flt_time_min + flt_dist * flt_time_per_deg);
if(flt_t LT flt_time_min, copy(flt_t, flt_time_min));
if(flt_t GT flt_time_max, copy(flt_t, flt_time_max));

tween(view.hlookat, calc(view.hlookat + flt_dh_signed), get(flt_t), easeOutQuad);
tween(view.vlookat, get(flt_v), get(flt_t), easeOutQuad);
